INSERT INTO `v1_3d4fe1be70ab128ff2cfc4bafbc5bd005d82cd6fcc726ec2e3dba1aaea7baa7c` VALUES (0.2, 111031, "nyx_idle_normal", "", "nyx_302_yuni_02", 0, 3, 13020018, 0.2, 1, 302);
INSERT INTO `v1_3d4fe1be70ab128ff2cfc4bafbc5bd005d82cd6fcc726ec2e3dba1aaea7baa7c` VALUES ("", 111031, "", "", "だが怪我の功名、\n探していた部品を\n偶然にも発見できた", 10, 11, 13020019, "", "", 302);
INSERT INTO `v1_3d4fe1be70ab128ff2cfc4bafbc5bd005d82cd6fcc726ec2e3dba1aaea7baa7c` VALUES ("", 5, "", "", "", "", 93, 13020020, "", "", 302);
INSERT INTO `v1_3d4fe1be70ab128ff2cfc4bafbc5bd005d82cd6fcc726ec2e3dba1aaea7baa7c` VALUES ("", 111031, "", "", 0, "", 4, 13020021, "", "", 302);
INSERT INTO `v1_3d4fe1be70ab128ff2cfc4bafbc5bd005d82cd6fcc726ec2e3dba1aaea7baa7c` VALUES ("", 111031, "", "", "nyx_cmn_03", 1, 3, 13020022, 0.2, "", 302);
INSERT INTO `v1_3d4fe1be70ab128ff2cfc4bafbc5bd005d82cd6fcc726ec2e3dba1aaea7baa7c` VALUES ("", 111031, "", "", "ふむ…これは僥倖\nかくなる上は再び\n潜航してみるか…", 10, 11, 13020023, "", "", 302);
INSERT INTO `v1_3d4fe1be70ab128ff2cfc4bafbc5bd005d82cd6fcc726ec2e3dba1aaea7baa7c` VALUES ("", 0, "", "", "", "", 91, 13020024, "", "", 302);
INSERT INTO `v1_3d4fe1be70ab128ff2cfc4bafbc5bd005d82cd6fcc726ec2e3dba1aaea7baa7c` VALUES ("", 111031, "", "", "nyx_301_yuni_01", 1, 3, 13020025, 0.2, "", 302);
INSERT INTO `v1_3d4fe1be70ab128ff2cfc4bafbc5bd005d82cd6fcc726ec2e3dba1aaea7baa7c` VALUES ("", 111031, "", "", "存外意義あるものだ\n資材ダイビングとか\nいう新種の探索行は", 10, 11, 13020026, "", "", 302);
INSERT INTO `v1_3d4fe1be70ab128ff2cfc4bafbc5bd005d82cd6fcc726ec2e3dba1aaea7baa7c` VALUES ("", 0, "", "", 1, "", 91, 13020027, "", "", 302);
INSERT INTO `v1_3d4fe1be70ab128ff2cfc4bafbc5bd005d82cd6fcc726ec2e3dba1aaea7baa7c` VALUES ("", 111031, "", "", "まあ万一溺れたとて\n後輩たちの誰ぞが\nきっと気付くだろう", 10, 11, 13020028, "", "", 302);
INSERT INTO `v1_3d4fe1be70ab128ff2cfc4bafbc5bd005d82cd6fcc726ec2e3dba1aaea7baa7c` VALUES ("", 0, "", "", 1, "", 91, 13020029, "", "", 302);
INSERT INTO `v1_3d4fe1be70ab128ff2cfc4bafbc5bd005d82cd6fcc726ec2e3dba1aaea7baa7c` VALUES ("", 111031, "nyx_302_yuni_04", "", "nyx_302_yuni_03", 0, 3, 13020030, 0.2, 1, 302);
INSERT INTO `v1_3d4fe1be70ab128ff2cfc4bafbc5bd005d82cd6fcc726ec2e3dba1aaea7baa7c` VALUES ("", 111031, "", "", "是非もなし\nいざ往かん！", 10, 11, 13020031, "", "", 302);
INSERT INTO `v1_3d4fe1be70ab128ff2cfc4bafbc5bd005d82cd6fcc726ec2e3dba1aaea7baa7c` VALUES ("", 0, "", "", 1, "", 91, 13020032, "", "", 302);
INSERT INTO `v1_3d4fe1be70ab128ff2cfc4bafbc5bd005d82cd6fcc726ec2e3dba1aaea7baa7c` VALUES ("", 1.5, "", "", "", "", 93, 13020033, "", "", 302);
INSERT INTO `v1_3d4fe1be70ab128ff2cfc4bafbc5bd005d82cd6fcc726ec2e3dba1aaea7baa7c` VALUES ("", 111031, "", "", "む。奥に入りすぎた\nこれは…出られぬ！\n誰かー！　誰か―！", 10, 11, 13020034, "", "", 302);
INSERT INTO `v1_3d4fe1be70ab128ff2cfc4bafbc5bd005d82cd6fcc726ec2e3dba1aaea7baa7c` VALUES ("", 0, "", "", "", "", 91, 13020035, "", "", 302);
